INSERT INTO monster VALUES (380,'Ghoul','Ghast',NULL,'Medium','Undead',NULL,'4d12+3 (29 hp)','+3','30 ft. (6 squares)','17 (+3 Dex, +4 natural), touch 12, flat-footed 14','+2','+5','Bite +5 melee (1d8+3 plus paralysis)','Bite +5 melee (1d8+3 plus paralysis) and 2 claws +3 melee (1d4+1 plus paralysis)','5 ft.','5 ft.','Ghoul fever, paralyis, stench','Darkvision 60 ft., undead traits, +2 turn resistance','Fort +1, Ref +4, Will +6','Str 17, Dex 17, Con -, Int 13, Wis 14, Cha 16','Balance +7, Climb +9, Hide +8, Jump +9, Move Silently +8, Spot +8',NULL,'Multiattack, Toughness',NULL,'Any','Solitary, gang (2-4), or pack (2-4 plus 7-12 ghouls)','3','Standard','Always chaotic evil','5-8 HD (Medium)','-','Ghoul Fever (Su), Paralysis (Ex), Stench (Ex)','Ghast; CR 3; Medium undead; HD 4d12+3; hp 29; Init +3; Spd 30 ft. (6 squares); AC 17 (+3 dex, +4 natural), touch 12, flat-footed 14; Base Atk +2; Grp +5; Atk +5 melee (1d8+3 plus paralysis, bite); Full Atk +5 melee (1d8+3 plus paralysis, bite) and +3 melee (1d4+1 plus paralysis, 2 claws); Space/Reach 5 ft./5 ft.; SA Ghoul fever, paralyis, stench; SQ Darkvision 60 ft., undead traits, +2 turn resistance; AL CE; SV Fort +1, Ref +4, Will +6; Str 17, Dex 17, Con -, Int 13, Wis 14, Cha 16\n\nSkills and Feats: Balance +7, Climb +9, Hide +8, Jump +9, Move Silently +8, Spot +8; Multiattack, Toughness','\n      <div topic=\"Ghoul\" level=\"2\"><p><h2>Ghoul</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Ghast</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Medium Undead<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>4d12+3 (29 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>17 (+3 Dex, +4 natural), touch 12, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+2/+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Bite +5 melee (1d8+3 plus paralysis)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Bite +5 melee (1d8+3 plus paralysis) and 2 claws +3 melee (1d4+1 plus paralysis)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Ghoul fever, paralyis, stench<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Darkvision 60 ft., undead traits, +2 turn resistance<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +1, Ref +4, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 17, Dex 17, Con -, Int 13, Wis 14, Cha 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Balance +7, Climb +9, Hide +8, Jump +9, Move Silently +8, Spot +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Multiattack, Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n <td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary, gang (2-4), or pack (2-4 plus 7-12 ghouls)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>5-8 HD (Medium)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n</tr>\n</table><p>Ghouls speak the languages they spoke in life (usually Common).</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Ghouls try to attack with surprise whenever possible. They strike from behind tombstones and burst from shallow graves.</p><div topic=\"Ghoul Fever\" level=\"8\"><p><b>Ghoul Fever (Su):</b> Disease-bite, Fortitude DC 12, incubation period 1 day, damage 1d3 Con and 1d3 Dex. The save DC is Charisma-based.</p><p>An afflicted humanoid who dies of ghoul fever rises as a ghoul at the next midnight. A humanoid who becomes a ghoul in this way retains none of the abilities it possessed in life. It is not under the control of any other ghouls, but it hungers for the flesh of the living and behaves like a normal ghoul in all respects. A humanoid of 4 Hit Dice or more rises as a ghast, not a ghoul.</p>\n</div><div topic=\"Paralysis\" level=\"8\"><p><b>Paralysis (Ex):</b> Those hit by a ghoul\'s bite or claw attack must succeed on a DC 12 Fortitude save or be paralyzed for 1d4+1 rounds. Elves have immunity to this paralysis. The save DC is Charisma-based.</p>\n</div>\n</div><div topic=\"Lacedon\" level=\"3\"><p><h3>Lacedon</h3></p><p>These cousins of the ghoul have the aquatic subtype. They lurk near hidden reefs or other places where ships are likely to meet their end. They have a base land speed of 30 feet and a swim speed of 30 feet and are found only in aquatic environments.</p>\n</div><div topic=\"Ghast\" level=\"3\"><p><h3>Ghast</h3></p><p>Although these creatures look just like their lesser kin, they are far more deadly and cunning.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Ghoul Fever\" level=\"8\"><p><b>Ghoul Fever (Su):</b> Disease-bite, Fortitude DC 15, incubation period 1 day, damage 1d3 Con and 1d3 Dex. The save DC is Charisma-based.</p>\n</div><div topic=\"Paralysis\" level=\"8\"><p><b>Paralysis (Ex):</b> Those hit by a ghast\'s bite or claw attack must succeed on a DC 15 Fortitude save or be paralyzed for 1d4+1 rounds. Even elves can be affected by this paralysis. The save DC is Charisma-based.</p>\n</div><div topic=\"Stench\" level=\"8\"><p><b>Stench (Ex):</b> The stink of death and corruption surrounding these creatures is overwhelming. Living creatures within 10 feet must succeed on a DC 15 Fortitude save or be sickened for 1d6+4 minutes. A creature that successfully saves cannot be affected again by the same ghast\'s stench for 24 hours. A <i>delay poison</i> or <i>neutralize poison</i> spell removes the effect from a sickened creature. Creatures with immunity to poison are unaffected, and creatures resistant to poison receive their normal bonus on their saving throws. The save DC is Charisma-based.</p><p/>\n</div>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (381,'Giant','Cloud Giant',NULL,'Huge','Giant','Air','17d8+102 (178 hp)','+1','50 ft. (10 squares)','25 (-2 size, +1 Dex, +12 natural, +4 chain shirt), touch 9, flat-footed 24','+12','+32','Gargantuan morningstar +22 melee (4d6+18) or slam +22 melee (1d6+12) or rock +12 ranged (2d8+12)','Gargantuan morningstar +22/+17/+12 melee (4d6+18) or 2 slams +22 melee (1d6+12) or rock +12 ranged (2d8+12)','15 ft.','15 ft.','Rock throwing, spell-like abilities','Low-light vision, oversized weapon, rock catching, scent','Fort +16, Ref +6, Will +10','Str 35, Dex 13, Con 23, Int 12, Wis 16, Cha 13','Climb +19, Craft (any one) +11, Diplomacy +3, Intimidate +11, Listen +15, Perform (stringed instruments) +2, Sense Motive +9, Spot +15',NULL,'Awesome Blow, Cleave, Improved Bull Rush, Improved Overrun, Iron Will, Power Attack',NULL,'Temperate mountains','Solitary, gang (2-4), family (2-4 plus 35% noncombatants plus 1 sorcerer or cleric of 4th-7th level plus 2-5 griffons or 2-8 dire lions), or band (6-9 plus 1 sorcerer or cleric of 4th-7th level plus 2-5 griffons or 2-8 dire lions)','11','Standard coins; double goods; standard items','Usually neutral good or neutral evil','By character class','-','Oversized Weapon (Ex), Rock Catching (Ex), Rock Throwing (Ex)','Cloud giant; CR 11; Huge giant (air); HD 17d8+102; hp 178; Init +1; Spd 50 ft. (10 squares); AC 25 (-2 size, +1 dex, +12 natural, +4 chain shirt), touch 9, flat-footed 24; Base Atk +12; Grp +32; Atk +22 melee (4d6+18, gargantuan morningstar) or +22 melee (1d6+12, slam) or +12 ranged (2d8+12, rock); Full Atk +22 /+17/+12 melee (4d6+18, gargantuan morningstar) or +22 melee (1d6+12, 2 slams) or +12 ranged (2d8+12, rock); Space/Reach 15 ft./15 ft.; SA Rock throwing, spell-like abilities; SQ Low-light vision, oversized weapon, rock catching, scent; AL NG; SV Fort +16, Ref +6, Will +10; Str 35, Dex 13, Con 23, Int 12, Wis 16, Cha 13\n\nSkills and Feats: Climb +19, Craft (any one) +11, Diplomacy +3, Intimidate +11, Listen +15, Perform (stringed instruments) +2, Sense Motive +9, Spot +15; Awesome Blow, Cleave, Improved Bull Rush, Improved Overrun, Iron Will, Power Attack','\n      <div topic=\"Cloud Giant\" level=\"3\"><p><h3>Cloud Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Cloud Giant</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Giant (Air)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>17d8+102 (178 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>25 (-2 size, +1 Dex, +12 natural, +4 chain shirt), touch 9, flat-footed 24<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+12/+32<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Gargantuan morningstar +22 melee (4d6+18) or slam +22 melee (1d6+12) or rock +12 ranged (2d8+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Gargantuan morningstar +22/+17/+12 melee (4d6+18) or 2 slams +22 melee (1d6+12) or rock +12 ranged (2d8+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rock throwing, spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, oversized weapon, rock catching, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +16, Ref +6, Will +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 35, Dex 13, Con 23, Int 12, Wis 16, Cha 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +19, Craft (any one) +11, Diplomacy +3, Intimidate +11, Listen +15, Perform (stringed instruments) +2, Sense Motive +9, Spot +15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Awesome Blow, Cleave, Improved Bull Rush, Improved Overrun, Iron Will, Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-4), family (2-4 plus 35% noncombatants plus 1 sorcerer or cleric of 4th-7th level plus 2-5 griffons or 2-8 dire lions), or band (6-9 plus 1 sorcerer or cleric of 4th-7th level plus 2-5 griffons or 2-8 dire lions)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard coins; double goods; standard items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral good or neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Cloud giants\' skin ranges in color from milky white to light sky blue. Their hair is silvery white or brass, and their eyes are iridescent blue. Adult males are about 18 feet tall and weigh about 5,000 pounds. Females are slightly shorter and lighter. Cloud giants can live to be 400 years old.</p><p>Cloud giants dress in the finest clothing available and wear jewelry. To many, appearance indicates station: The better the clothes and the finer the jewelry, the more important the wearer. They also appreciate music, and most can play one or more instruments (the harp is a favorite).</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Cloud giants fight in well-organized units, using carefully developed battle plans. They prefer to fight from a position above their opponents. A favorite tactic is to circle the enemies, barraging them with rocks while the giants with magical abilities confound them with spells.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 140 feet for a cloud giant\'s thrown rocks.</p>\n</div><div topic=\"Oversized Weapon\" level=\"8\"><p><b>Oversized Weapon (Ex):</b> A cloud giant wields a great, two-handed morningstar (big enough for Gargantuan creatures) without penalty.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 3/day-<i>levitate</i> (self plus 2,000 pounds), <i>obscuring mist</i>; 1/day-<i>fog cloud</i>. Caster level 15th.</p><p/>\n</div>\n</div><div topic=\"Cloud Giant Characters\" level=\"4\"><p><h4>Cloud Giant Characters</h4></p><p>Most cloud giant groups include a sorcerer or a cleric.</p><p>Good-aligned clerics have access to two of the following domains: Good, Healing, Strength, or Sun. Evil-aligned clerics have access to two of the following domains: Death, Evil, or Trickery.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (382,'Giant','Fire Giant',NULL,'Large','Giant','Fire','15d8+75 (142 hp)','-1','30 ft. in half-plate armor (6 squares); base speed 40 ft.','23 (-1 size, -1 Dex, +8 natural, +7 half-plate armor), touch 8, flat-footed 23','+11','+25','Greatsword +20 melee (3d6+15) or slam +20 melee (1d4+10) or rock +10 ranged (2d6+10 plus 2d6 fire)','Greatsword +20/+15/+10 melee (3d6+15) or 2 slams +20 melee (1d4+10) or rock +10 ranged (2d6+10 plus 2d6 fire)','10 ft.','10 ft.','Rock throwing','Immunity to fire, low-light vision, rock catching, vulnerability to cold','Fort +14, Ref +4, Will +9','Str 31, Dex 9, Con 21, Int 10, Wis 14, Cha 11','Climb +9, Craft (any one) +6, Intimidate +6, Jump +9, Spot +14',NULL,'Cleave, Great Cleave, Improved Overrun, Improved Sunder, Iron Will, Power Attack',NULL,'Warm mountains','Solitary, gang (2-5), band (6-9 plus 35% noncombatants plus 1 adept or cleric of 1st or 2nd level), hunting/raiding party (6-9 plus 1 adept or sorcerer of 3rd-5th level plus 2-4 hell hounds and 2-3 trolls or ettins), or tribe (21-30 plus 1 adept, cleric, or sorcerer of 6th or 7th level plus 12-30 hell hounds, 12-22 trolls, 5-12 ettins, and 1-2 young red dragons)','10','Standard','Often lawful evil','By character class','+4','Rock Catching (Ex), Rock Throwing (Ex)','Fire giant; CR 10; Large giant (fire); HD 15d8+75; hp 142; Init -1; Spd 30 ft. in half-plate armor (6 squares); base speed 40 ft.; AC 23 (-1 size, -1 dex, +8 natural, +7 half-plate armor), touch 8, flat-footed 23; Base Atk +11; Grp +25; Atk +20 melee (3d6+15, greatsword) or +20 melee (1d4+10, slam) or +10 ranged (2d6+10 plus 2d6 fire, rock); Full Atk +20 /+15/+10 melee (3d6+15, greatsword) or +20 melee (1d4+10, 2 slams) or +10 ranged (2d6+10 plus 2d6 fire, rock); Space/Reach 10 ft./10 ft.; SA Rock throwing; SQ Immunity to fire, low-light vision, rock catching, vulnerability to cold; AL LE; SV Fort +14, Ref +4, Will +9; Str 31, Dex 9, Con 21, Int 10, Wis 14, Cha 11\n\nSkills and Feats: Climb +9, Craft (any one) +6, Intimidate +6, Jump +9, Spot +14; Cleave, Great Cleave, Improved Overrun, Improved Sunder, Iron Will, Power Attack','\n      <div topic=\"Fire Giant\" level=\"3\"><p><h3>Fire Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Fire Giant</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Giant (Fire)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>15d8+75 (142 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. in half-plate armor (6 squares); base speed 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>23 (-1 size, -1 Dex, +8 natural, +7 half-plate armor), touch 8, flat-footed 23<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+11/+25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Greatsword +20 melee (3d6+15) or slam +20 melee (1d4+10) or rock +10 ranged (2d6+10 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Greatsword +20/+15/+10 melee (3d6+15) or 2 slams +20 melee (1d4+10) or rock +10 ranged (2d6+10 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rock throwing<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Immunity to fire, low-light vision, rock catching, vulnerability to cold<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +14, Ref +4, Will +9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 31, Dex 9, Con 21, Int 10, Wis 14, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +9, Craft (any one) +6, Intimidate +6, Jump +9, Spot +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Cleave, Great Cleave, Improved Overrun, Improved Sunder, Iron Will, Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-5), band (6-9 plus 35% noncombatants plus 1 adept or cleric of 1st or 2nd level), hunting/raiding party (6-9 plus 1 adept or sorcerer of 3rd-5th level plus 2-4 hell hounds and 2-3 trolls or ettins), or tribe (21-30 plus 1 adept, cleric, or sorcerer of 6th or 7th level plus 12-30 hell hounds, 12-22 trolls, 5-12 ettins, and 1-2 young red dragons)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n</table><p>Some fire giants have bright orange hair.. An adult male is 12 feet tall, has a chest that measures 9 feet around, and weighs about 7,000 pounds. Females are slightly shorter and lighter. Fire giants can live to be 350 years old.</p><p>Fire giants wear sturdy cloth or leather garments colored red, orange, yellow, or black. Warriors wear helmets and half-plate armor of blackened steel.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Fire giants heat their rocks in a nearby fire, geyser, or lava pools, so that they deal extra fire damage. They favor magic flaming swords in melee (when they can get them). They are also fond of grabbing smaller opponents and tossing them somewhere very hot.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 120 feet for a fire giant\'s thrown rocks.</p>\n</div>\n</div><div topic=\"Fire Giant Characters\" level=\"5\"><p><h5>Fire Giant Characters</h5></p><p>Most groups of fire giants include clerics. A fire giant cleric has access to two of the following domains: Evil, Law, Trickery, or War (most choose Trickery or War, some choose both).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (383,'Giant','Frost Giant',NULL,'Large','Giant','Cold','14d8+70 (133 hp)','-1','40 ft. (8 squares)','21 (-1 size, -1 Dex, +9 natural, +4 chain shirt), touch 8, flat-footed 21','+10','+23','Greataxe +18 melee (3d6+13/x3) or slam +18 melee (1d4+9) or rock +9 ranged (2d6+9)','Huge greataxe +18/+13 melee (3d6+13/x3) or 2 slams +18 melee (1d4+9) or rock +9 ranged (2d6+9)','10 ft.','10 ft.','Rock throwing','Immunity to cold, low-light vision, rock catching, vulnerability to fire','Fort +14, Ref +3, Will +6','Str 29, Dex 9, Con 21, Int 10, Wis 14, Cha 11','Climb +13, Craft (any one) +6, Intimidate +6, Jump +17, Spot +12',NULL,'Cleave, Great Cleave, Improved Overrun, Improved Sunder, Power Attack',NULL,'Cold mountains','Solitary, gang (2-5), band (6-9 plus 35% noncombatants plus 1 adept or cleric of 1st or 2nd level), hunting/raiding party (6-9 plus 35% noncombatants plus 1 adept or sorcerer of 3rd-5th level plus 2-4 winter wolves and 2-3 ogres), or tribe (21-30 plus 1 adept, cleric, or sorcerer of 6th or 7th level plus 12-30 winter wolves, 12-22 ogres, and 1-2 young white dragons)','9','Standard','Often chaotic evil','By character class','+4','Aura of Despair (Su), Aura of Evil (Ex), Command Undead (Su), Dark Blessing (Su), Detect Good (Sp), Rock Catching (Ex), Rock Throwing (Ex), Smite Good (Su)','Frost giant; CR 9; Large giant (cold); HD 14d8+70; hp 133; Init -1; Spd 40 ft. (8 squares); AC 21 (-1 size, -1 dex, +9 natural, +4 chain shirt), touch 8, flat-footed 21; Base Atk +10; Grp +23; Atk +18 melee (3d6+13/x3, greataxe) or +18 melee (1d4+9, slam) or +9 ranged (2d6+9, rock); Full Atk +18 /+13 melee (3d6+13/x3, huge greataxe) or +18 melee (1d4+9, 2 slams) or +9 ranged (2d6+9, rock); Space/Reach 10 ft./10 ft.; SA Rock throwing; SQ Immunity to cold, low-light vision, rock catching, vulnerability to fire; AL CE; SV Fort +14, Ref +3, Will +6; Str 29, Dex 9, Con 21, Int 10, Wis 14, Cha 11\n\nSkills and Feats: Climb +13, Craft (any one) +6, Intimidate +6, Jump +17, Spot +12; Cleave, Great Cleave, Improved Overrun, Improved Sunder, Power Attack','\n      <div topic=\"Frost Giant\" level=\"3\"><p><h3>Frost Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Frost Giant</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Giant (Cold)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>14d8+70 (133 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>21 (-1 size, -1 Dex, +9 natural, +4 chain shirt), touch 8, flat-footed 21<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+10/+23<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Greataxe +18 melee (3d6+13/x3) or slam +18 melee (1d4+9) or rock +9 ranged (2d6+9)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Huge greataxe +18/+13 melee (3d6+13/x3) or 2 slams +18 melee (1d4+9) or rock +9 ranged (2d6+9)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b> <br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rock throwing<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Immunity to cold, low-light vision, rock catching, vulnerability to fire<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +14, Ref +3, Will +6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 29, Dex 9, Con 21, Int 10, Wis 14, Cha 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +13, Craft (any one) +6, Intimidate +6, Jump +17, Spot +12<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Cleave, Great Cleave, Improved Overrun, Improved Sunder, Power Attack<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Cold mountains<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-5), band (6-9 plus 35% noncombatants plus 1 adept or cleric of 1st or 2nd level), hunting/raiding party (6-9 plus 35% noncombatants plus 1 adept or sorcerer of 3rd-5th level plus 2-4 winter wolves and 2-3 ogres), or tribe (21-30 plus 1 adept, cleric, or sorcerer of 6th or 7th level plus 12-30 winter wolves, 12-22 ogres, and 1-2 young white dragons)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often chaotic evil<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n\n</tr>\n</table><p>A frost giant\'s hair can be light blue or dirty yellow, and its eyes usually match its hair color. Frost giants dress in skins and pelts, along with any jewelry they own. Frost giant warriors add chain shirts and metal helmets decorated with horns or feathers.</p><p>An adult male is about 15 feet tall and weighs about 2,800 pounds. Females are slightly shorter and lighter, but otherwise identical with males. Frost giants can live to be 250 years old.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Frost giants usually start combat at a distance, throwing rocks until they run out of ammunition or the opponent closes, then wading in with their enormous battleaxes.</p><p>A favorite tactic is to lay an ambush by hiding buried in the snow at the top of an icy or snowy slope, where opponents will have difficulty reaching them.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 120 feet for a frost giant\'s thrown rocks.</p><p/>\n</div>\n</div><div topic=\"Frost Giant Jarl\" level=\"4\"><p><h4>Frost Giant Jarl</h4></p><p>A frost giant leader is often a barbarian, cleric, fighter, or sorcerer, but some of the most evil and ruthless frost giants become blackguards.</p><p>The frost giant jarl described here has all the qualities and abilities of a typical frost giant, as well as other abilities (see the statistics block) from being a blackguard. Details on some of these abilities follow.</p><div topic=\"Aura of Despair\" level=\"8\"><p><b>Aura of Despair (Su):</b> This jarl radiates a malign aura that causes enemies within 10 feet of him to take a -2 penalty on all saving throws.</p>\n</div><div topic=\"Aura of Evil\" level=\"8\"><p><b>Aura of Evil (Ex):</b> This jarl radiates a strong aura of evil (see the <i>detect evil</i> spell) as an 8th-level cleric of an evil deity.</p>\n</div><div topic=\"Command Undead\" level=\"8\"><p><b>Command Undead (Su):</b> This jarl can command and rebuke undead as a 6th-level cleric.</p>\n</div><div topic=\"Dark Blessing\" level=\"8\"><p><b>Dark Blessing (Su):</b> This jarl applies his Charisma modifier as a bonus on all saving throws.</p>\n</div><div topic=\"Detect Good\" level=\"8\"><p><b><i>Detect Good</i> (Sp):</b> At will, this jarl can use <i>detect</i> <i>good</i> as a spell-like ability, duplicating the effect of the <i>detect</i> <i>good</i> spell.</p>\n</div><div topic=\"Poison Use\" level=\"8\"><p><b>Poison Use:</b> Blackguards are skilled in the use of poison and never risk accidentally poisoning themselves when applying poison to a blade.</p>\n</div><div topic=\"Smite Good\" level=\"8\"><p><b>Smite Good (Su):</b> Twice per day, this jarl may attempt to smite good with one normal melee attack. He adds his +4 Charisma modifier to his attack roll and deals 8 points of extra damage (1 per blackguard level) if the attack hits. If he accidentally smites a creature that is not good, the smite has no effect but it is still used up for that day.</p><p><i>Typical Blackguard</i> <i>Spells Prepared</i> (3/1; save DC 11 + spell level): 1st-<i>cause fear</i> <i>doom</i>,  <i>magic weapon</i>; 2nd-<i>bull\'s</i> <i>strength</i>.</p><p><i>Possessions: +2 frost greataxe</i>,  <i>+2 full plate armor</i>,  <i>cloak of Charisma +2</i> <i>ring of minor energy resistance (fire)</i>,  2 doses of bloodroot poison. (Benefits of these items are included in the statistics block.)</p><p/>\n</div>\n</div><div topic=\"Frost Giant Characters\" level=\"4\"><p><h4>Frost Giant Characters</h4></p><p>Many groups of frost giants include clerics. A frost giant cleric has access to two of the following domains: Chaos, Destruction, Evil, or War (most choose Destruction or War, some choose both).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (384,'Giant','Frost Giant Jarl, 8th-Level Blackguard',NULL,'Large','Giant','Cold','14d8+84 plus 8d10+48 (231 hp)','+5','30 ft. in +2 full plate armor (6 squares); base speed 40 ft.','29 (-1 size, +1 Dex, +9 natural, +10 +2 full plate armor), touch 10, flat-footed 28','+18','+33','+2 frost greataxe +30 melee (3d6+18/x3 plus 1d6 cold) or slam +28 melee (1d4+11) or rock +18 ranged (2d6+11)','+2 frost greataxe +30/+25/+20/+15 melee (3d6+18/x3 plus 1d6 cold) or 2 slams +28 melee (1d4+11) or rock +18 ranged (2d6+11)','10 ft.','10 ft.','Rock throwing, smite good, sneak attack +2d6','Aura of despair, aura of evil, command undead, dark blessing, detect good, immunity to cold, low-light vision, poison use, fire resistance 10, rock catching, vulnerability to fire','Fort +25, Ref +13, Will +13','Str 32, Dex 12, Con 22, Int 10, Wis 12, Cha 18','Climb +17, Hide +2, Jump +17, Knowledge (religion) +2, Ride +11, Spot +5',NULL,'Cleave, Great Cleave, Improved Initiative, Improved Sunder, Iron Will, Lightning Reflexes, Power Attack, Quick Draw',NULL,'Cold mountains','Solitary or with tribe','17','Standard','Always chaotic evil','By character class','-','Aura of Despair (Su), Aura of Evil (Ex), Command Undead (Su), Dark Blessing (Su), Detect Good (Sp), Rock Catching (Ex), Rock Throwing (Ex), Smite Good (Su)','8th-level blackguard frost giant jarl; CR 17; Large giant (cold); HD 14d8+84 plus 8d10+48; hp 231; Init +5; Spd 30 ft. in +2 full plate armor (6 squares); base speed 40 ft.; AC 29 (-1 size, +1 dex, +9 natural, +10 +2 full plate armor), touch 10, flat-footed 28; Base Atk +18; Grp +33; Atk +30 melee (3d6+18/x3 plus 1d6 cold, +2 frost greataxe) or +28 melee (1d4+11, slam) or +18 ranged (2d6+11, rock); Full Atk +30 /+25/+20/+15 melee (3d6+18/x3 plus 1d6 cold, +2 frost greataxe) or +28 melee (1d4+11, 2 slams) or +18 ranged (2d6+11, rock); Space/Reach 10 ft./10 ft.; SA Rock throwing, smite good, sneak attack +2d6; SQ Aura of despair, aura of evil, command undead, dark blessing, detect good,  immunity to cold, low-light vision, poison use, fire resistance 10, rock catching, vulnerability to fire; AL CE; SV Fort +25, Ref +13, Will +13; Str 32, Dex 12, Con 22, Int 10, Wis 12, Cha 18\n\nSkills and Feats: Climb +17, Hide +2, Jump +17, Knowledge (religion) +2, Ride +11, Spot +5; Cleave, Great Cleave, Improved Initiative, Improved Sunder, Iron Will, Lightning Reflexes, Power Attack, Quick Draw','\n      <div topic=\"Frost Giant\" level=\"3\"><p><h3>Frost Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Frost Giant Jarl, 8th-Level Blackguard</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Large Giant (Cold)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>14d8+84 plus 8d10+48 (231 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>30 ft. in <i>+2 full plate armor</i> (6 squares); base speed 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>29 (-1 size, +1 Dex, +9 natural, +10 <i>+2 full plate armor</i>), touch 10, flat-footed 28<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+18/+33<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td><i>+2 frost greataxe</i> +30 melee (3d6+18/x3 plus 1d6 cold) or slam +28 melee (1d4+11) or rock +18 ranged (2d6+11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td><i>+2 frost greataxe</i> +30/+25/+20/+15 melee (3d6+18/x3 plus 1d6 cold) or 2 slams +28 melee (1d4+11) or rock +18 ranged (2d6+11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b> <br/></td>\n\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Rock throwing, smite good, sneak attack +2d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Aura of despair, aura of evil, command undead, dark blessing, <i>detect good</i>,  immunity to cold, low-light vision, poison use, fire resistance 10, rock catching, vulnerability to fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +25, Ref +13, Will +13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 32, Dex 12, Con 22, Int 10, Wis 12, Cha 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Climb +17, Hide +2, Jump +17, Knowledge (religion) +2, Ride +11, Spot +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Cleave, Great Cleave, Improved Initiative, Improved Sunder, Iron Will, Lightning Reflexes, Power Attack, Quick Draw<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Cold mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary or with tribe<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n</tr>\n</table><p>A frost giant\'s hair can be light blue or dirty yellow, and its eyes usually match its hair color. Frost giants dress in skins and pelts, along with any jewelry they own. Frost giant warriors add chain shirts and metal helmets decorated with horns or feathers.</p><p>An adult male is about 15 feet tall and weighs about 2,800 pounds. Females are slightly shorter and lighter, but otherwise identical with males. Frost giants can live to be 250 years old.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Frost giants usually start combat at a distance, throwing rocks until they run out of ammunition or the opponent closes, then wading in with their enormous battleaxes.</p><p>A favorite tactic is to lay an ambush by hiding buried in the snow at the top of an icy or snowy slope, where opponents will have difficulty reaching them.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 120 feet for a frost giant\'s thrown rocks.</p><p/>\n</div>\n</div><div topic=\"Frost Giant Jarl\" level=\"4\"><p><h4>Frost Giant Jarl</h4></p><p>A frost giant leader is often a barbarian, cleric, fighter, or sorcerer, but some of the most evil and ruthless frost giants become blackguards.</p><p>The frost giant jarl described here has all the qualities and abilities of a typical frost giant, as well as other abilities (see the statistics block) from being a blackguard. Details on some of these abilities follow.</p><div topic=\"Aura of Despair\" level=\"8\"><p><b>Aura of Despair (Su):</b> This jarl radiates a malign aura that causes enemies within 10 feet of him to take a -2 penalty on all saving throws.</p>\n</div><div topic=\"Aura of Evil\" level=\"8\"><p><b>Aura of Evil (Ex):</b> This jarl radiates a strong aura of evil (see the <i>detect evil</i> spell) as an 8th-level cleric of an evil deity.</p>\n</div><div topic=\"Command Undead\" level=\"8\"><p><b>Command Undead (Su):</b> This jarl can command and rebuke undead as a 6th-level cleric.</p>\n</div><div topic=\"Dark Blessing\" level=\"8\"><p><b>Dark Blessing (Su):</b> This jarl applies his Charisma modifier as a bonus on all saving throws.</p>\n</div><div topic=\"Detect Good\" level=\"8\"><p><b><i>Detect Good</i> (Sp):</b> At will, this jarl can use <i>detect</i> <i>good</i> as a spell-like ability, duplicating the effect of the <i>detect</i> <i>good</i> spell.</p>\n</div><div topic=\"Poison Use\" level=\"8\"><p><b>Poison Use:</b> Blackguards are skilled in the use of poison and never risk accidentally poisoning themselves when applying poison to a blade.</p>\n</div><div topic=\"Smite Good\" level=\"8\"><p><b>Smite Good (Su):</b> Twice per day, this jarl may attempt to smite good with one normal melee attack. He adds his +4 Charisma modifier to his attack roll and deals 8 points of extra damage (1 per blackguard level) if the attack hits. If he accidentally smites a creature that is not good, the smite has no effect but it is still used up for that day.</p><p><i>Typical Blackguard</i> <i>Spells Prepared</i> (3/1; save DC 11 + spell level): 1st-<i>cause fear</i> <i>doom</i>,  <i>magic weapon</i>; 2nd-<i>bull\'s</i> <i>strength</i>.</p><p><i>Possessions: +2 frost greataxe</i>,  <i>+2 full plate armor</i>,  <i>cloak of Charisma +2</i> <i>ring of minor energy resistance (fire)</i>,  2 doses of bloodroot poison. (Benefits of these items are included in the statistics block.)</p><p/>\n</div>\n</div><div topic=\"Frost Giant Characters\" level=\"4\"><p><h4>Frost Giant Characters</h4></p><p>Many groups of frost giants include clerics. A frost giant cleric has access to two of the following domains: Chaos, Destruction, Evil, or War (most choose Destruction or War, some choose both).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (385,'Giant','Hill Giant',NULL,'Large','Giant',NULL,'12d8+48 (102 hp)','-1','30 ft. in hide armor (6 squares); base speed 40 ft.','20 (-1 size, -1 Dex, +9 natural, +3 hide armor), touch 8, flat-footed 20','+9','+20','Greatclub +16 melee (2d8+10) or slam +15 melee (1d4+7) or rock +8 ranged (2d6+7)','Greatclub +16/+11 melee (2d8+10) or 2 slams +15 melee (1d4+7) or rock +8 ranged (2d6+7)','10 ft.','10 ft.','Rock throwing','Low-light vision, rock catching','Fort +12, Ref +3, Will +4','Str 25, Dex 8, Con 19, Int 6, Wis 10, Cha 7','Climb +7, Jump +7, Listen +3, Spot +6',NULL,'Cleave, Improved Bull Rush, Power Attack, Improved Sunder, Weapon Focus (greatclub)',NULL,'Temperate hills','Solitary, gang (2-5), band (6-9 plus 35% noncombatants), hunting/raiding party (6-9 plus 2-4 dire wolves), or tribe (21-30 plus 35% noncombatants plus 12-30 dire wolves, 2-4 ogres, and 12-22 orcs)','7','Standard','Often chaotic evil','By character class','+4','Rock Catching (Ex), Rock Throwing (Ex)','Hill giant; CR 7; Large giant; HD 12d8+48; hp 102; Init -1; Spd 30 ft. in hide armor (6 squares); base speed 40 ft.; AC 20 (-1 size, -1 dex, +9 natural, +3 hide armor), touch 8, flat-footed 20; Base Atk +9; Grp +20; Atk +16 melee (2d8+10, greatclub) or +15 melee (1d4+7, slam) or +8 ranged (2d6+7, rock); Full Atk +16 /+11 melee (2d8+10, greatclub) or +15 melee (1d4+7, 2 slams) or +8 ranged (2d6+7, rock); Space/Reach 10 ft./10 ft.; SA Rock throwing; SQ Low-light vision, rock catching; AL CE; SV Fort +12, Ref +3, Will +4; Str 25, Dex 8, Con 19, Int 6, Wis 10, Cha 7\n\nSkills and Feats: Climb +7, Jump +7, Listen +3, Spot +6; Cleave, Improved Bull Rush, Improved Sunder, Power Attack, Weapon Focus (greatclub)','\n      <div topic=\"Hill Giant\" level=\"3\"><p><h3>Hill Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Hill Giant</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Giant<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d8+48 (102 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. in hide armor (6 squares); base speed 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (-1 size, -1 Dex, +9 natural, +3 hide armor), touch 8, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Greatclub +16 melee (2d8+10) or slam +15 melee (1d4+7) or rock +8 ranged (2d6+7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Greatclub +16/+11 melee (2d8+10) or 2 slams +15 melee (1d4+7) or rock +8 ranged (2d6+7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rock throwing<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, rock catching<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +12, Ref +3, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 25, Dex 8, Con 19, Int 6, Wis 10, Cha 7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +7, Jump +7, Listen +3, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Cleave, Improved Bull Rush, Power Attack, Improved Sunder, Weapon Focus (greatclub)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate hills<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-5), band (6-9 plus 35% noncombatants), hunting/raiding party (6-9 plus 2-4 dire wolves), or tribe (21-30 plus 35% noncombatants plus 12-30 dire wolves, 2-4 ogres, and 12-22 orcs)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n</table><p>Skin color among hill giants ranges from light tan to deep ruddy brown. Their hair is brown or black, with eyes the same color. Hill giants wear layers of crudely prepared hides with the fur left on. They seldom wash or repair their garments, preferring to simply add more hides as their old ones wear out.</p><p>Adults are about 10-1/2 feet tall and weigh about 1,100 pounds. Hill giants can live to be 200 years old.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Hill giants prefer to fight from high, rocky outcroppings, where they can pelt opponents with rocks and boulders while limiting the risk to themselves.</p><p>Hill giants love to make overrun attacks against smaller creatures when they first join battle. Thereafter, they stand fast and swing away with their massive clubs.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 120 feet for a hill giant\'s thrown rocks.</p><p/>\n</div>\n</div><div topic=\"Hill Giants as Characters\" level=\"4\"><p><h4>Hill Giants as Characters</h4></p><p>Reckless brutes of incredible strength but little wit, hill giant characters are never truly accepted into society. Yet they do well on its edges and frontiers, forging a strong and profitable existence.</p><p>Despite their rugged appearance and great size, their basically humanoid shape makes it easy for them to relate with more civilized folk.</p><p>Hill giant characters possess the following racial traits.</p><ul>\n <li>+14 Strength, -2 Dexterity, +8 Constitution, -4 Intelligence, -4 Charisma.</li>\n <li>Large size. -1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Hide checks, +4 bonus on grapple checks, lifting and carrying limits double those of Medium characters.</li>\n <li>Space/Reach: 10 feet/10 feet.</li>\n</ul><p>-A hill giant\'s base land speed is 40 feet.</p><ul>\n <li>Low-light vision.</li>\n <li>Racial Hit Dice: A hill giant begins with twelve levels of giant, which provide 12d8 Hit Dice, a base attack bonus of +8, and base saving throw bonuses of Fort +8, Ref +4, and Will +4.</li>\n <li>Racial Skills: A hill giant\'s giant levels give it skill points</li>\n</ul><p>equal to 15 x (2 + Int modifier). Its class skills are Climb, Jump, Listen, and Spot.</p><ul>\n <li>Racial Feats: A hill giant\'s giant levels give it five feats.</li>\n <li>+9 natural armor bonus.</li>\n <li>Special Attacks (see above): Rock throwing.</li>\n <li>Special Qualities (see above): Rock catching.</li>\n <li>Weapon and Armor Proficiency: A hill giant is automatically proficient with simple weapons, martial weapons, light and medium armor, and shields.</li>\n <li>Automatic Languages: Giant. Bonus Languages: Common, Draconic, Elven, Goblin, Orc.</li>\n <li>Favored Class: Barbarian.</li>\n <li>Level adjustment +4.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (386,'Giant','Stone Giant',NULL,'Large','Giant','Earth','14d8+56 (119 hp)','+2','30 ft. in hide armor (6 squares); base speed 40 ft.','25 (-1 size, +2 Dex, +11 natural, +3 hide), touch 11, flat-footed 23','+10','+22','Greatclub +17 melee (2d8+12) or slam +17 melee (1d4+8) or rock +11 ranged (2d8+12)','Greatclub +17/+12 melee (2d8+12) or 2 slams +17 melee (1d4+8) or rock +11 ranged (2d8+12)','10 ft.','10 ft.','Rock throwing','Darkvision 60 ft., low-light vision, rock catching','Fort +13, Ref +6, Will +7','Str 27, Dex 15, Con 19, Int 10, Wis 12, Cha 11','Climb +11, Hide +6*, Jump +11, Spot +12',NULL,'Combat Reflexes, Iron Will, Point Blank Shot, Power Attack, Precise Shot',NULL,'Temperate mountains','Solitary, gang (2-5), band (6-9 plus 35% noncombatants), hunting/raiding/trading party (6-9 plus 1 elder), or tribe (21-30 plus 35% noncombatants plus 1-3 elders and 3-6 dire bears)','8 (elder 9)','Standard','Usually neutral','By character class','+4 (elder +6)','Rock Catching (Ex), Rock Throwing (Ex)','Stone giant; CR 8 (elder 9); Large giant (earth); HD 14d8+56; hp 119; Init +2; Spd 30 ft. in hide armor (6 squares); base speed 40 ft.; AC 25 (-1 size, +2 dex, +11 natural, +3 hide), touch 11, flat-footed 23; Base Atk +10; Grp +22; Atk +17 melee (2d8+12, greatclub) or +17 melee (1d4+8, slam) or +11 ranged (2d8+12, rock); Full Atk +17 /+12 melee (2d8+12, greatclub) or +17 melee (1d4+8, 2 slams) or +11 ranged (2d8+12, rock); Space/Reach 10 ft./10 ft.; SA Rock throwing; SQ Darkvision 60 ft., low-light vision, rock catching; AL N; SV Fort +13, Ref +6, Will +7; Str 27, Dex 15, Con 19, Int 10, Wis 12, Cha 11\n\nSkills and Feats: Climb +11, Hide +6*, Jump +11, Spot +12; Combat Reflexes, Iron Will, Point Blank Shot, Power Attack, Precise Shot','\n      <div topic=\"Stone Giant\" level=\"3\"><p><h3>Stone Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Stone Giant</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Giant (Earth)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>14d8+56 (119 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. in hide armor (6 squares); base speed 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>25 (-1 size, +2 Dex, +11 natural, +3 hide), touch 11, flat-footed 23<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+10/+22<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Greatclub +17 melee (2d8+12) or slam +17 melee (1d4+8) or rock +11 ranged (2d8+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Greatclub +17/+12 melee (2d8+12) or 2 slams +17 melee (1d4+8) or rock +11 ranged (2d8+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rock throwing<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision, rock catching<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +13, Ref +6, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 27, Dex 15, Con 19, Int 10, Wis 12, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +11, Hide +6*, Jump +11, Spot +12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Combat Reflexes, Iron Will, Point Blank Shot, Power Attack, Precise Shot<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-5), band (6-9 plus 35% noncombatants), hunting/raiding/trading party (6-9 plus 1 elder), or tribe (21-30 plus 35% noncombatants plus 1-3 elders and 3-6 dire bears)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>8 (elder 9)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4 (elder +6)<br/></td>\n\n</tr>\n</table><p>Stone giants prefer thick leather garments, dyed in shades of brown and gray to match the stone around them. Adults are about 12 feet tall and weigh about 1,500 pounds. Stone giants can live to be 800 years old.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Stone giants fight from a distance whenever possible, but if they can\'t avoid melee, they use gigantic clubs chiseled out of stone. A favorite tactic of stone giants is to stand nearly motionless, blending in with the background, then move forward to throw rocks and surprise their foes.</p><div topic=\"Rock Throwing\" level=\"8\"><p><b>Rock Throwing (Ex):</b> The range increment is 180 feet for a stone giant\'s thrown rocks. It uses both hands when throwing a rock.</p>\n</div><div topic=\"Rock Catching\" level=\"8\"><p><b>Rock Catching (Ex):</b> A stone giant gains a +4 racial bonus on its Reflex save when attempting to catch a thrown rock.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> *A stone giant gains a +8 racial bonus on Hide checks in rocky terrain.</p><p/>\n</div>\n</div><div topic=\"Stone Giant Elders\" level=\"4\"><p><h4>Stone Giant Elders</h4></p><p>Some stone giants develop special abilities related to their environment. These giant elders have Charisma scores of at least 15 and spell-like abilities, which they use as 10th-level sorcerers. Once per day they can use <i>stone shape</i>,  <i>stone tell</i>,  and either <i>transmute rock to mud</i> or <i>transmute mud to rock</i> (DC 17). The save DC is Charisma-based. One in ten elders is a sorcerer, usually of 3rd to 6th level.</p><p/>\n</div><div topic=\"Stone Giants as Characters\" level=\"4\"><p><h4>Stone Giants as Characters</h4></p><p>Strong, silent loners, stone giant characters are a rare sight in human lands.</p><p>Stone giant characters possess the following racial traits.</p><ul>\n <li>+16 Strength, +4 Dexterity, +8 Constitution, +2 Wisdom.</li>\n <li>Large size. -1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Hide checks, +4 bonus on grapple checks, lifting and carrying limits double those of Medium characters.</li>\n <li>Space/Reach: 10 feet/10 feet.</li>\n</ul><p>-A stone giant\'s base land speed is 40 feet.</p><ul>\n <li>Darkvision out to 60 feet and low-light vision.</li>\n <li>Racial Hit Dice: A stone giant begins with fourteen levels of giant, which provide 14d8 Hit Dice, a base attack bonus of +10, and base saving throw bonuses of Fort +9, Ref +4, and Will +4.</li>\n <li>Racial Skills: A stone giant\'s giant levels give it skill points equal to 17 x?(2 + Int modifier). Its class skills are Climb, Hide, Listen, and Spot. A stone giant has a +8 racial bonus on Hide checks in rocky terrain.</li>\n <li>Racial Feats: A stone giant\'s giant levels give it five feats.</li>\n <li>+11 natural armor bonus.</li>\n <li>Special Attacks (see above): Rock throwing.</li>\n <li>Special Qualities (see above): Rock catching.</li>\n <li>Automatic Languages: Giant. Bonus Languages: Common, Draconic, Elven, Goblin, Orc.</li>\n <li>Favored Class: Barbarian.</li>\n <li>Level adjustment +4.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (387,'Giant','Storm Giant',NULL,'Huge','Giant',NULL,'19d8+114 (199 hp)','+2','35 ft. (7 squares), swim 30 ft. (6 squares) in breastplate; base speed 50 ft., swim 40 ft.','27 (-2 size, +2 Dex, +12 natural, +5 breastplate), touch 10, flat-footed 25','+14','+36','Greatsword +26 melee (4d6+21/19-20) or slam +26 melee (1d6+14) or composite longbow (+14 Str bonus) +14 ranged (3d6+14/x3)','Greatsword +26/+21/+16 melee (4d6+21/19-20) or 2 slams +26 melee (1d6+14) or composite longbow (+14 Str bonus) +14/+9/+4 ranged (3d6+14/x3)','15 ft.','15 ft.','Spell-like abilities','Freedom of movement, immunity to electricity, low-light vision, rock catching, water breathing','Fort +17, Ref +8, Will +13','Str 39, Dex 14, Con 23, Int 16, Wis 20, Cha 15','Climb +20, Concentration +26, Craft (any one) +13, Diplomacy +4, Intimidate +12, Jump +24, Listen +15, Perform (sing) +12, Sense Motive +15, Spot +25, Swim +18*',NULL,'Awesome Blow, Cleave, Combat Reflexes, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack',NULL,'Warm mountains','Solitary or family (2-4 plus 35% noncombatants plus 1 sorcerer or cleric of 7th-10th level plus 1-2 rocs, 2-5 griffons, or 2-8 sea cats)','13','Standard coins; double goods; standard items','Often chaotic good','By character class','-','Freedom of Movement (Su), Rock Catching (Ex), Rock Throwing (Ex), Water Breathing (Ex)','Storm giant; CR 13; Huge giant; HD 19d8+114; hp 199; Init +2; Spd 35 ft. (7 squares), swim 30 ft. (6 squares) in breastplate; base speed 50 ft., swim 40 ft.; AC 27 (-2 size, +2 dex, +12 natural, +5 breastplate), touch 10, flat-footed 25; Base Atk +14; Grp +36; Atk +26 melee (4d6+21/19-20, greatsword) or +26 melee (1d6+14, slam) or +14 Str bonus) +14 ranged (3d6+14/x3, composite longbow (); Full Atk +26 /+21/+16 melee (4d6+21/19-20, greatsword) or +26 melee (1d6+14, 2 slams) or +14 Str bonus) +14/+9/+4 ranged (3d6+14/x3, composite longbow (); Space/Reach 15 ft./15 ft.; SA Spell-like abilities; SQ Freedom of movement, immunity to electricity, low-light vision, rock catching, water breathing; AL CG; SV Fort +17, Ref +8, Will +13; Str 39, Dex 14, Con 23, Int 16, Wis 20, Cha 15\n\nSkills and Feats: Climb +20, Concentration +26, Craft (any one) +13, Diplomacy +4, Intimidate +12, Jump +24, Listen +15, Perform (sing) +12, Sense Motive +15, Spot +25, Swim +18*; Awesome Blow, Cleave, Combat Reflexes, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack','\n      <div topic=\"Storm Giant\" level=\"3\"><p><h3>Storm Giant</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Storm Giant</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Giant<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>19d8+114 (199 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>35 ft. (7 squares), swim 30 ft. (6 squares) in breastplate; base speed 50 ft., swim 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>27 (-2 size, +2 Dex, +12 natural, +5 breastplate), touch 10, flat-footed 25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+14/+36<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Greatsword +26 melee (4d6+21/19-20) or slam +26 melee (1d6+14) or composite longbow (+14 Str bonus) +14 ranged (3d6+14/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Greatsword +26/+21/+16 melee (4d6+21/19-20) or 2 slams +26 melee (1d6+14) or composite longbow (+14 Str bonus) +14/+9/+4 ranged (3d6+14/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Freedom of movement, immunity to electricity, low-light vision, rock catching, water breathing<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +17, Ref +8, Will +13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 39, Dex 14, Con 23, Int 16, Wis 20, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +20, Concentration +26, Craft (any one) +13, Diplomacy +4, Intimidate +12, Jump +24, Listen +15, Perform (sing) +12, Sense Motive +15, Spot +25, Swim +18*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Awesome Blow, Cleave, Combat Reflexes, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or family (2-4 plus 35% noncombatants plus 1 sorcerer or cleric of 7th-10th level plus 1-2 rocs, 2-5 griffons, or 2-8 sea cats)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard coins; double goods; standard items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often chaotic good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Very rarely, storm giants have violet skin. Violet-skinned storm giants have deep violet or blue-black hair with silvery gray or purple eyes. Adults are about 21 feet tall and weigh about 12,000 pounds. Storm giants can live to be 600 years old. Storm giants\' garb is usually a short, loose tunic belted at the waist, sandals or bare feet, and a headband. They wear a few pieces of simple but finely crafted jewelry, anklets (favored by barefoot giants), rings, or circlets being most common. They live quiet, reflective lives and spend their time musing about the world, composing and playing music, and tilling their land or gathering food.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Storm giants use weapons and spell-like abilities instead of throwing rocks. Their composite longbows have a range increment of 180 feet.</p><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 1/day-<i>call lightning</i> (DC 15), <i>chain lightning</i> (DC 18). Caster level 15th. 2/day-<i>control weather</i>, <i>levitate</i>. Caster level 20th. The save DCs are Charisma-based.</p>\n</div><div topic=\"Freedom of Movement\" level=\"8\"><p><b>Freedom of Movement (Su):</b> Storm giants have a continuous freedom of movement ability as the spell (caster level 20th). The effect can be dispelled, but the storm giant can create it again on its next turn as a free action.</p>\n</div><div topic=\"Water Breathing\" level=\"8\"><p><b>Water Breathing (Ex):</b> Storm giants can breathe underwater indefinitely and can freely use their spell-like abilities while submerged.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A storm giant has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line. *Storm giants ignore all weight penalties for gear carried when swimming.</p>\n</div>\n</div><div topic=\"Storm Giant Characters\" level=\"5\"><p><h5>Storm Giant Characters</h5></p><p>About 20% of adult storm giants are sorcerers or clerics. A storm giant cleric has access to two of the following domains: Chaos, Good, Protection, or War.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (388,'Gibbering Mouther','Gibbering Mouther',NULL,'Medium','Aberration',NULL,'4d8+24 (42 hp)','+1','10 ft. (2 squares), swim 20 ft.','19 (+1 Dex, +8 natural), touch 11, flat-footed 18','+3','+3','Bite +4 melee (1) or spittle +4 ranged touch (1d4 acid plus blindness)','6 bites +4 melee (1) and spittle +4 ranged touch (1d4 acid plus blindness)','5 ft.','5 ft.','Gibbering, spittle, improved grab, blood drain, engulf, ground manipulation','Amorphous, damage reduction 5/bludgeoning, darkvision 60 ft.','Fort +7, Ref +4, Will +5','Str 10, Dex 13, Con 22, Int 4, Wis 13, Cha 13','Listen +4, Spot +9, Swim +8',NULL,'Lightning Reflexes, Weapon Finesse',NULL,'Underground','Solitary','5','None','Usually neutral','5-12 HD (Large)','-','Amorphous (Ex), Blood Drain (Ex), Engulf (Ex), Gibbering (Su), Ground Manipulation (Su), Improved Grab (Ex), Spittle (Ex)','Gibbering mouther; CR 5; Medium aberration; HD 4d8+24; hp 42; Init +1; Spd 10 ft. (2 squares), swim 20 ft.; AC 19 (+1 dex, +8 natural), touch 11, flat-footed 18; Base Atk +3; Grp +3; Atk +4 melee (1, bite) or +4 ranged touch (1d4 acid plus blindness, spittle); Full Atk +4 melee (1, 6 bites) and +4 ranged touch (1d4 acid plus blindness, spittle); Space/Reach 5 ft./5 ft.; SA Gibbering, spittle, improved grab, blood drain, engulf, ground manipulation; SQ Amorphous, damage reduction 5/bludgeoning, darkvision 60 ft.; AL N; SV Fort +7, Ref +4, Will +5; Str 10, Dex 13, Con 22, Int 4, Wis 13, Cha 13\n\nSkills and Feats: Listen +4, Spot +9, Swim +8; Lightning Reflexes, Weapon Finesse','\n      <div topic=\"Gibbering Mouther\" level=\"2\"><p><h2>Gibbering Mouther</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Gibbering Mouther</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Aberration<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d8+24 (42 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), swim 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>19 (+1 Dex, +8 natural), touch 11, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +4 melee (1) or spittle +4 ranged touch (1d4 acid plus blindness)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>6 bites +4 melee (1) and spittle +4 ranged touch (1d4 acid plus blindness)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Gibbering, spittle, improved grab, blood drain, engulf, ground manipulation<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Amorphous, damage reduction 5/bludgeoning, darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +7, Ref +4, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 13, Con 22, Int 4, Wis 13, Cha 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +4, Spot +9, Swim +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Lightning Reflexes, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-12 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A gibbering mouther is a horrible creature seemingly drawn from a lunatic\'s nightmares. Although not evil, it thirsts after bodily fluids and seems to prefer the blood of intelligent creatures.</p><p>A gibbering mouther is about 3 feet across and 3 to 4 feet high. It weighs about 200 pounds.</p><p>Gibbering mouthers can speak Common, but seldom say anything other than gibberish.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A gibbering mouther attacks by shooting out strings of protoplasmic flesh, each ending in one or more eyes and a mouth that bites at the enemy. A mouther can send out a total of six such members in any round.</p><div topic=\"Gibbering\" level=\"8\"><p><b>Gibbering (Su):</b> As soon as a mouther spots something edible, it begins a constant gibbering as a free action. All creatures (other than mouthers) within a 60-foot spread must succeed on a DC 13 Will save or be affected as though by a <i>confusion</i> spell for 1d2 rounds. This is a sonic mind-affecting compulsion effect. A creature that successfully saves cannot be affected by the same gibbering mouther\'s gibbering for 24 hours. The save DC is Charisma-based.</p>\n</div><div topic=\"Spittle\" level=\"8\"><p><b>Spittle (Ex):</b> As a free action every round, a gibbering mouther fires a stream of spittle at one opponent within 30 feet. The mouther makes a ranged touch attack; if it hits, it deals 1d4 points of acid damage, and the target must succeed on a DC 18 Fortitude save or be blinded for 1d4 rounds. Eyeless creatures are immune to the blinding effect, but are still subject to the acid damage. The save DC is Constitution-based.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a gibbering mouther must hit with a bite attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity.</p>\n</div><div topic=\"Blood Drain\" level=\"8\"><p><b>Blood Drain (Ex):</b> On a successful grapple check after grabbing, that mouth attaches to the opponent. It automatically deals bite damage and drains blood, dealing 1 point of Constitution damage each round. A mouth can be ripped off (dealing 1 point of damage) with a DC 12 Strength check or severed by a successful sunder attempt (the mouth has 2 hit points).</p><p>A severed mouth continues to bite and drain blood for 1d4 rounds after such an attack. A creature whose Constitution is reduced to 0 is killed.</p>\n</div><div topic=\"Engulf\" level=\"8\"><p><b>Engulf (Ex):</b> A gibbering mouther can try to engulf a Medium or smaller opponent grabbed by three or more mouths.</p><p>The opponent must succeed on a DC 14 Reflex save or fall and be engulfed. In the next round, the mouther makes twelve bite attacks instead of six (each with a +4 attack bonus). An engulfed creature cannot attack the mouther from within. The previously attached mouths are now free to attack others. The save DC is Strength-based and includes a +2 racial bonus.</p>\n</div><div topic=\"Ground Manipulation\" level=\"8\"><p><b>Ground Manipulation (Su):</b> At will, as a standard action, a gibbering mouther can cause stone and earth in all adjacent squares to become a morass akin to quicksand. Softening earth, sand, or the like takes 1 round, while stone takes 2 rounds. Anyone other than the mouther in that area must take a move-equivalent action to avoid becoming mired (treat as being pinned).</p>\n</div><div topic=\"Amorphous\" level=\"8\"><p><b>Amorphous (Ex):</b> A gibbering mouther is not subject to critical hits. It cannot be flanked.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Thanks to their multiple eyes, gibbering mouthers have a +4 racial bonus on Spot checks.</p><p>A gibbering mouther has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It always can choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (389,'Girallon','Girallon',NULL,'Large','Magical Beast',NULL,'7d10+20 (58 hp)','+3','40 ft. (8 squares), climb 40 ft.','16 (-1 size, +3 Dex, +4 natural), touch 12, flat-footed 15','+7','+17','Claw +12 melee (1d4+6)','4 claws +12 melee (1d4+6) and bite +7 melee (1d8+3)','10 ft.','10 ft.','Rend 2d4+9','Darkvision 60 ft., low-light vision, scent','Fort +7, Ref +8, Will +5','Str 22, Dex 17, Con 14, Int 2, Wis 12, Cha 7','Climb +14, Move Silently +8, Spot +6',NULL,'Iron Will, Toughness (2)',NULL,'Warm forests','Solitary or company (5-8)','6','None','Always neutral','8-10 HD (Large); 11-21 HD (Huge)','-','Rend (Ex)','Girallon; CR 6; Large magical beast; HD 7d10+20; hp 58; Init +3; Spd 40 ft. (8 squares), climb 40 ft.; AC 16 (-1 size, +3 dex, +4 natural), touch 12, flat-footed 15; Base Atk +7; Grp +17; Atk +12 melee (1d4+6, claw); Full Atk +12 melee (1d4+6, 4 claws) and +7 melee (1d8+3, bite); Space/Reach 10 ft./10 ft.; SA Rend 2d4+9; SQ Darkvision 60 ft., low-light vision, scent; AL N; SV Fort +7, Ref +8, Will +5; Str 22, Dex 17, Con 14, Int 2, Wis 12, Cha 7\n\nSkills and Feats: Climb +14, Move Silently +8, Spot +6; Iron Will, Toughness (2)','\n      <div topic=\"Girallon\" level=\"2\"><p><h2>Girallon</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Girallon</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>7d10+20 (58 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares), climb 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (-1 size, +3 Dex, +4 natural), touch 12, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+7/+17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +12 melee (1d4+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>4 claws +12 melee (1d4+6) and bite +7 melee (1d8+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rend 2d4+9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +7, Ref +8, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 22, Dex 17, Con 14, Int 2, Wis 12, Cha 7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +14, Move Silently +8, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Iron Will, Toughness (2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or company (5-8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>8-10 HD (Large); 11-21 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Girallons are savage, magical cousins of the gorilla. When moving on the ground, a girallon walks on its legs and lower arms. An adult girallon is about 8 feet tall, broad-chested, and covered in thick, pure white fur. It weighs about 800 pounds.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A solitary girallon usually conceals itself in the branches of a tree or under a pile of leaves and brush, with only its nose showing. When it spots or scents prey, it charges to the attack. A girallon picks up prey that is small enough to carry and withdraws, often vanishing into the trees before the victim\'s companions can do anything to retaliate. Against larger foes, a girallon seeks to tear a single opponent to bits as quickly as it can.</p><div topic=\"Rend\" level=\"8\"><p><b>Rend (Ex):</b> A girallon that hits with two or more claw attacks latches onto the opponent\'s body and tears the flesh. This attack automatically deals an extra 2d4+12 points of damage.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A girallon has a +8 racial bonus on Climb checks and can always choose to take 10 on a Climb check, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (390,'Gnoll','Gnoll',NULL,'Medium','Humanoid','Gnoll','2d8+2 (11 hp)','+0','30 ft. (6 squares)','15 (+1 natural, +2 leather armor, +2 heavy steel shield), touch 10, flat-footed 15','+1','+3','Battleaxe +3 melee (1d8+2/x3) or shortbow +1 ranged (1d6/x3)','Battleaxe +3 melee (1d8+2/x3) or shortbow +1 ranged (1d6/x3)','5 ft.','5 ft.','-','Darkvision 60 ft.','Fort +4, Ref +0, Will +0','Str 15, Dex 10, Con 13, Int 8, Wis 11, Cha 8','Listen +2, Spot +3',NULL,'Power Attack',NULL,'Warm plains','Solitary, pair, hunting party (2-5 and 1-2 hyenas), band (10-100 plus 50% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level and 5-8 hyenas), or tribe (20-200 plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, and 7-12 hyenas; underground lairs also have 1-3 trolls)','1','Standard','Usually chaotic evil','By character class','+1','','Gnoll; CR 1; Medium humanoid (gnoll); HD 2d8+2; hp 11; Init +0; Spd 30 ft. (6 squares); AC 15 (+1 natural, +2 leather armor, +2 heavy steel shield), touch 10, flat-footed 15; Base Atk +1; Grp +3; Atk +3 melee (1d8+2/x3, battleaxe) or +1 ranged (1d6/x3, shortbow); Full Atk +3 melee (1d8+2/x3, battleaxe) or +1 ranged (1d6/x3, shortbow); Space/Reach 5 ft./5 ft.; SA -; SQ Darkvision 60 ft.; AL CE; SV Fort +4, Ref +0, Will +0; Str 15, Dex 10, Con 13, Int 8, Wis 11, Cha 8\n\nSkills and Feats: Listen +2, Spot +3; Power Attack','\n      <div topic=\"Gnoll\" level=\"2\"><p><h2>Gnoll</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Gnoll</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Humanoid (Gnoll)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8+2 (11 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+1 natural, +2 leather armor, +2 heavy steel shield), touch 10, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Battleaxe +3 melee (1d8+2/x3) or shortbow +1 ranged (1d6/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Battleaxe +3 melee (1d8+2/x3) or shortbow +1 ranged (1d6/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +0, Will +0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 10, Con 13, Int 8, Wis 11, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +2, Spot +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, hunting party (2-5 and 1-2 hyenas), band (10-100 plus 50% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level and 5-8 hyenas), or tribe (20-200 plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, and 7-12 hyenas; underground lairs also have 1-3 trolls)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n</table><p>Gnolls are hyena-headed, evil humanoids that wander in loose tribes. Most gnolls have dirty yellow or reddish-brown fur. A gnoll is a nocturnal carnivore, preferring intelligent creatures for food because they scream more. A gnoll is about 7-1/2 feet tall and weighs 300 pounds. Gnolls speak Gnoll.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Gnolls like to attack when they have the advantage of numbers, using horde tactics and their physical strength to overwhelm and knock down their opponents. They show little discipline when fighting unless they have a strong leader; at such times, they can maintain ranks and fight as a unit. While they do not usually prepare traps, they do use ambushes and try to attack from a flanking position. Because of its shield, a gnoll\'s modifier on Hide checks (untrained) is -2, which means gnolls always take special care to seek favorable conditions when laying ambushes (such as darkness, cover, or some other form of advantageous terrain).</p>\n</div><div topic=\"Gnolls as Characters\" level=\"3\"><p><h3>Gnolls as Characters</h3></p><p>Gnoll characters possess the following racial traits.</p><ul>\n <li>Strength +4, Constitution +2, Intelligence -2, Charisma -2.</li>\n <li>Size Medium.</li>\n</ul><p>-A gnoll\'s base land speed is 30 feet.</p><ul>\n <li>Darkvision out to 60 feet.</li>\n <li>Racial Hit Dice: A gnoll begins with two levels of humanoid, which provide 2d8 Hit Dice, a base attack bonus of +1, and base saving throw bonuses of Fort +3, Ref +0, and Will +0.</li>\n <li>Racial Skills: A gnoll\'s humanoid levels give it skill points equal to 5 x?(2 + Int modifier). Its class skills are Listen and Spot.</li>\n <li>Racial Feats: A gnoll\'s humanoid levels give it one feat.</li>\n <li>+1 natural armor bonus.</li>\n <li>Automatic Languages: Gnoll. Bonus Languages: Common, Draconic, Elven, Goblin, Orc.</li>\n <li>Favored Class: Ranger.</li>\n <li>Level adjustment +1.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (391,'Gnome','Gnome, 1st-Level Warrior',NULL,'Small','Humanoid','Gnome','1d8+2 (6 hp)','+0','20 ft. (4 squares)','16 (+1 size, +4 chain shirt, +1 light shield), touch 11, flat-footed 16','+1','-3','Longsword +2 melee (1d6/19-20) or light crossbow +3 ranged (1d6/19-20)','Longsword +2 melee (1d6/19-20) or light crossbow +3 ranged (1d6/19-20)','5 ft.','5 ft.','-','Gnome traits','Fort +4, Ref +0, Will -1','Str 11, Dex 11, Con 14, Int 10, Wis 9, Cha 8','Hide +3, Listen +1, Spot +1',NULL,'Weapon Focus (light crossbow)',NULL,'Temperate hills (Forest gnomes: Temperate forests)','Company (2-4), squad (11-20 plus 1 leader of 3rd-6th level and 2 3rd-level lieutenants), or band (30-50 plus 1 3rd-level sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, and 2-5 dire badgers)','1/2','Standard','Usually neutral good','By character class','+0','Gnome Traits (Ex)','1st-level warrior gnome; CR 1/2; Small humanoid (gnome); HD 1d8+2; hp 6; Init +0; Spd 20 ft. (4 squares); AC 16 (+1 size, +4 chain shirt, +1 light shield), touch 11, flat-footed 16; Base Atk +1; Grp -3; Atk +2 melee (1d6/19-20, longsword) or +3 ranged (1d6/19-20, light crossbow); Full Atk +2 melee (1d6/19-20, longsword) or +3 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA -; SQ Gnome traits; AL NG; SV Fort +4, Ref +0, Will -1; Str 11, Dex 11, Con 14, Int 10, Wis 9, Cha 8\n\nSkills and Feats: Hide +3, Listen +1, Spot +1; Weapon Focus (light crossbow)','\n      <div topic=\"Gnome\" level=\"2\"><p><h2>Gnome</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Gnome, 1st-Level Warrior</b><br/></td> \n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Humanoid (Gnome)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+2 (6 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+1 size, +4 chain shirt, +1 light shield), touch 11, flat-footed 16<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Longsword +2 melee (1d6/19-20) or light crossbow +3 ranged (1d6/19-20)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b> <br/></td>\n<td>Longsword +2 melee (1d6/19-20) or light crossbow +3 ranged (1d6/19-20)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Gnome traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +0, Will -1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 11, Dex 11, Con 14, Int 10, Wis 9, Cha 8<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +3, Listen +1, Spot +1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (light crossbow)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate hills (Forest gnomes: Temperate forests)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Company (2-4), squad (11-20 plus 1 leader of 3rd-6th level and 2 3rd-level lieutenants), or band (30-50 plus 1 3rd-level sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, and 2-5 dire badgers)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral good<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+0<br/></td>\n\n\n</tr>\n</table><p>Gnomes stand 3 to 3-1/2 feet tall and weigh 40 to 45 pounds. Their skin color ranges from dark tan to woody brown, their hair is fair, and their eyes can be any shade of blue. Gnome males prefer short, carefully trimmed beards. Gnomes generally wear leather or earth tones, though they decorate their clothes with intricate stitching or fine jewelry. Gnomes reach adulthood at about age 40, and they live about 350 years, though some can live almost 500 years.</p><p>Gnomes speak their own language, Gnome. Most gnomes who travel outside gnome lands (as traders, tinkers, or adventurers) know Common, while warriors in gnome settlements usually learn Goblin.</p><p>Most gnomes encountered outside their home are warriors; the information in the statistics block is for one of 1st level.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Gnomes prefer misdirection and deception over direct confrontation.</p><p>They would rather befuddle or embarrass foes (other than goblinoids or kobolds) than kill them.</p><p>Gnomes make heavy use of illusion magic and carefully prepared ambushes and traps whenever they can.</p><div topic=\"Gnome Traits\" level=\"8\"><p><b>Gnome Traits (Ex):</b> Gnomes possess the following racial traits.</p><ul>\n <li>+2 Constitution, -2 Strength.</li>\n <li>Small size. +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Hide checks, -4 penalty on grapple checks, lifting and carrying limits 3/4 those of Medium characters.</li>\n</ul><p>-A gnome\'s base land speed is 20 feet.</p><ul>\n <li>Low-light vision.</li>\n <li>Weapon Familiarity: Gnomes may treat gnome hooked hammers as martial weapons rather than exotic weapons.</li>\n <li>+2 racial bonus on saving throws against illusions.</li>\n <li>Add +1 to the Difficulty Class for all saving throws against illusion spells cast by gnomes. This adjustment stacks with those from similar effects, such as the Spell Focus feat.</li>\n <li>+1 racial bonus on attack rolls against kobolds and goblinoids (including goblins, hobgoblins, and bugbears).</li>\n <li>+4 dodge bonus to Armor Class against creatures of the giant type (such as ogres, trolls, and hill giants).</li>\n <li>+2 racial bonus on Listen checks.</li>\n <li>+2 racial bonus on Craft (alchemy) checks.</li>\n <li>Automatic Languages: Common, Gnome. Bonus Languages: Draconic, Dwarven, Elven, Giant, Goblin, Orc.</li>\n <li>Spell-Like Abilities: 1/day-<i>speak with animals</i> (burrowing mammal only, duration 1 minute). A gnome with a Charisma score of at least 10 also has the following spell-like abilities: 1/day-<i>dancing lights</i>,  <i>ghost sound</i>,  <i>prestidigitation</i>. Caster level 1st; save DC 10 + gnome\'s Cha modifier + spell level.</li>\n <li>Favored Class: Bard.</li>\n</ul><p>The gnome warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Subraces\" level=\"3\"><p><h3>Subraces</h3></p><p>The information above is for rock gnomes, the most common variety.</p><p>There are two other major gnome subraces, which differ from rock gnomes as follows.</p><div topic=\"Svirfneblin\" level=\"5\"><p><h5>Svirfneblin</h5></p><p>Also called deep gnomes, svirfneblin are said to dwell in great cities deep underground.</p><p>A svirfneblin has wiry, rock-colored skin usually medium brown to brownish gray. Only males are bald; females have stringy gray hair. The average svirfneblin lifespan is 250 years.</p><p>Svirfneblin speak Gnome, Common, and Undercommon.</p><div topic=\"Svirfneblin Traits\" level=\"8\"><p><b>Svirfneblin Traits (Ex):</b> These traits are in addition to the rock gnome traits, except where noted.</p><ul>\n <li>-2 Strength, +2 Dexterity, +2 Wisdom, -4 Charisma. These adjustments replace the rock gnome\'s ability score adjustments.</li>\n <li>Stonecunning: This ability grants deep gnomes a +2 racial bonus on Search checks to notice unusual stonework. A deep gnome who merely comes within 10 feet of unusual stonework can make a Search check as though actively searching, and can use the Search skill to find stonework traps as a rogue can. A svirfneblin can also intuit depth, sensing the approximate distance underground as naturally as a human can sense which way is up.</li>\n <li>Darkvision out to 120 feet and low-light vision.</li>\n <li>Spell resistance equal to 11 + class levels.</li>\n <li>+2 racial bonus on all saving throws (figured into the statistics for the character presented here). This trait replaces the rock gnome\'s racial bonus on saving throws against illusions.</li>\n <li>Add +1 to the Difficulty Class for all saving throws against illusion spells cast by svirfneblin. This adjustment stacks with those from similar effects, such as the Spell Focus feat.</li>\n <li>+1 racial bonus on attack rolls against kobolds and goblinoids.</li>\n <li>+4 dodge bonus to Armor Class against all creatures (figured into the statistics for the character presented here). This trait replaces the rock gnome\'s dodge bonus against giants.</li>\n <li>Automatic Languages: Undercommon, Gnome, Common. Bonus Languages: Dwarven, Elven, Giant, Goblin, Orc, Terran. This trait replaces the rock gnome\'s automatic and bonus languages.</li>\n <li>Spell-Like Abilities: 1/day-<i>blindness/deafness</i> (typical save DC 13), <i>blur</i>,  <i>disguise self</i>. Caster level equals the svirfneblin\'s class levels. The save DC is Charisma-based and include a +4 racial modifier. This trait replaces the rock gnome\'s spell-like abilities.</li>\n <li>Nondetection (Su): A svirfneblin has a continuous nondetection ability as the spell (caster level equal to class levels).</li>\n <li>+2 racial bonus on Craft (alchemy) and Listen checks.</li>\n <li>+2 racial bonus on Hide checks, which improves to +4 underground.</li>\n <li>Favored Class: Rogue.</li>\n <li>Level adjustment +3.</li>\n</ul><p>The svirfneblin warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p><p>Challenge Rating: Svirfneblin with levels in NPC classes have a CR equal to their character level. Svirfneblin with levels in PC classes have a CR equal to their character level +1.</p>\n</div>\n</div><div topic=\"Forest Gnome\" level=\"5\"><p><h5>Forest Gnome</h5></p><p>They are the smallest of all the gnomes, averaging 2 to 2-1/2 feet in height, but look just like regular gnomes except with bark-colored or gray-green skin, and eyes that can be brown or green as well as blue. A very long-lived people, forest gnomes have an average life expectancy of 500 years.</p><div topic=\"Forest Gnome Traits\" level=\"8\"><p><b>Forest Gnome Traits (Ex):</b> These traits are in addition to the rock gnome traits, except where noted.</p><p>-<i>pass without trace</i> (Su): A forest gnome has the innate ability to use <i>pass without trace</i> (self only, as a free action) as the spell cast by a druid of the forest gnome\'s class levels.</p><ul>\n <li>+1 racial bonus on attack rolls against kobolds, goblinoids, orcs, and reptilian humanoids.</li>\n <li>Automatic Languages: Gnome, Elven, Sylvan, and a simple language that enables them to communicate on a very basic level with forest animals (this replaces the rock gnome\'s <i>speak with animals</i> ability). Bonus Languages: Common, Draconic, Dwarven, Giant, Goblin, Orc. This trait replaces the rock gnome\'s automatic and bonus languages.</li>\n <li>+4 racial bonus on Hide checks, which improves to +8 in a wooded area.</li>\n</ul><p/>\n</div>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (392,'Gnome','Svirfneblin, 1st-Level Warrior',NULL,'Small','Humanoid','Gnome','1d8+4 (8 hp)','+1','15 ft. in banded mail armor (3 squares); base speed 20 ft.','23 (+1 size, +1 Dex, +4 dodge, +6 banded mail, +1 buckler), touch 16, flat-footed 18','+1','-3','Heavy pick +2 melee (1d4/x4) or light crossbow +3 ranged (1d6/19-20)','Heavy pick +2 melee (1d4/x4) or light crossbow +3 ranged (1d6/19-20)','5 ft.','5 ft.','Spell-like abilities','Gnome traits, svirfneblin traits, spell resistance 12','Fort +5, Ref +3, Will +2','Str 11, Dex 13, Con 12, Int 10, Wis 11, Cha 4','Hide +2, Listen +2, Spot +2',NULL,'Toughness',NULL,'Underground','Company (2-4), squad (11-20 plus 1 leader of 3rd-6th level and 2 3rd-level lieutenants), or band (30-50 plus 1 3rd-level sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, and 2-5 Medium earth elementals)','1','Standard','Usually neutral','By character class','+3','Gnome Traits (Ex), Svirfneblin Traits (Ex)','1st-level warrior svirfneblin; CR 1; Small humanoid (gnome); HD 1d8+4; hp 8; Init +1; Spd 15 ft. in banded mail armor (3 squares); base speed 20 ft.; AC 23 (+1 size, +1 dex, +4 dodge, +6 banded mail, +1 buckler), touch 16, flat-footed 18; Base Atk +1; Grp -3; Atk +2 melee (1d4/x4, heavy pick) or +3 ranged (1d6/19-20, light crossbow); Full Atk +2 melee (1d4/x4, heavy pick) or +3 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Spell-like abilities; SQ Gnome traits, svirfneblin traits, spell resistance 12; AL N; SV Fort +5, Ref +3, Will +2; Str 11, Dex 13, Con 12, Int 10, Wis 11, Cha 4\n\nSkills and Feats: Hide +2, Listen +2, Spot +2; Toughness','\n      <div topic=\"Gnome\" level=\"2\"><p><h2>Gnome</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n <td><b>Svirfneblin, 1st-Level Warrior</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Small Humanoid (Gnome)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>1d8+4 (8 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>15 ft. in banded mail armor (3 squares); base speed 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>23 (+1 size, +1 Dex, +4 dodge, +6 banded mail, +1 buckler), touch 16, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+1/-3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Heavy pick +2 melee (1d4/x4) or light crossbow +3 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b> <br/></td>\n\n<td>Heavy pick +2 melee (1d4/x4) or light crossbow +3 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Gnome traits, svirfneblin traits, spell resistance 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +5, Ref +3, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 11, Dex 13, Con 12, Int 10, Wis 11, Cha 4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Hide +2, Listen +2, Spot +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Company (2-4), squad (11-20 plus 1 leader of 3rd-6th level and 2 3rd-level lieutenants), or band (30-50 plus 1 3rd-level sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, and 2-5 Medium earth elementals)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>+3<br/></td>\n\n</tr>\n</table><p>Gnomes stand 3 to 3-1/2 feet tall and weigh 40 to 45 pounds. Their skin color ranges from dark tan to woody brown, their hair is fair, and their eyes can be any shade of blue. Gnome males prefer short, carefully trimmed beards. Gnomes generally wear leather or earth tones, though they decorate their clothes with intricate stitching or fine jewelry. Gnomes reach adulthood at about age 40, and they live about 350 years, though some can live almost 500 years.</p><p>Gnomes speak their own language, Gnome. Most gnomes who travel outside gnome lands (as traders, tinkers, or adventurers) know Common, while warriors in gnome settlements usually learn Goblin.</p><p>Most gnomes encountered outside their home are warriors; the information in the statistics block is for one of 1st level.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Gnomes prefer misdirection and deception over direct confrontation.</p><p>They would rather befuddle or embarrass foes (other than goblinoids or kobolds) than kill them.</p><p>Gnomes make heavy use of illusion magic and carefully prepared ambushes and traps whenever they can.</p><div topic=\"Gnome Traits\" level=\"8\"><p><b>Gnome Traits (Ex):</b> Gnomes possess the following racial traits.</p><ul>\n <li>+2 Constitution, -2 Strength.</li>\n <li>Small size. +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Hide checks, -4 penalty on grapple checks, lifting and carrying limits 3/4 those of Medium characters.</li>\n</ul><p>-A gnome\'s base land speed is 20 feet.</p><ul>\n <li>Low-light vision.</li>\n <li>Weapon Familiarity: Gnomes may treat gnome hooked hammers as martial weapons rather than exotic weapons.</li>\n <li>+2 racial bonus on saving throws against illusions.</li>\n <li>Add +1 to the Difficulty Class for all saving throws against illusion spells cast by gnomes. This adjustment stacks with those from similar effects, such as the Spell Focus feat.</li>\n <li>+1 racial bonus on attack rolls against kobolds and goblinoids (including goblins, hobgoblins, and bugbears).</li>\n <li>+4 dodge bonus to Armor Class against creatures of the giant type (such as ogres, trolls, and hill giants).</li>\n <li>+2 racial bonus on Listen checks.</li>\n <li>+2 racial bonus on Craft (alchemy) checks.</li>\n <li>Automatic Languages: Common, Gnome. Bonus Languages: Draconic, Dwarven, Elven, Giant, Goblin, Orc.</li>\n <li>Spell-Like Abilities: 1/day-<i>speak with animals</i> (burrowing mammal only, duration 1 minute). A gnome with a Charisma score of at least 10 also has the following spell-like abilities: 1/day-<i>dancing lights</i>,  <i>ghost sound</i>,  <i>prestidigitation</i>. Caster level 1st; save DC 10 + gnome\'s Cha modifier + spell level.</li>\n <li>Favored Class: Bard.</li>\n</ul><p>The gnome warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Subraces\" level=\"3\"><p><h3>Subraces</h3></p><p>The information above is for rock gnomes, the most common variety.</p><p>There are two other major gnome subraces, which differ from rock gnomes as follows.</p><div topic=\"Svirfneblin\" level=\"5\"><p><h5>Svirfneblin</h5></p><p>Also called deep gnomes, svirfneblin are said to dwell in great cities deep underground.</p><p>A svirfneblin has wiry, rock-colored skin usually medium brown to brownish gray. Only males are bald; females have stringy gray hair. The average svirfneblin lifespan is 250 years.</p><p>Svirfneblin speak Gnome, Common, and Undercommon.</p><div topic=\"Svirfneblin Traits\" level=\"8\"><p><b>Svirfneblin Traits (Ex):</b> These traits are in addition to the rock gnome traits, except where noted.</p><ul>\n <li>-2 Strength, +2 Dexterity, +2 Wisdom, -4 Charisma. These adjustments replace the rock gnome\'s ability score adjustments.</li>\n <li>Stonecunning: This ability grants deep gnomes a +2 racial bonus on Search checks to notice unusual stonework. A deep gnome who merely comes within 10 feet of unusual stonework can make a Search check as though actively searching, and can use the Search skill to find stonework traps as a rogue can. A svirfneblin can also intuit depth, sensing the approximate distance underground as naturally as a human can sense which way is up.</li>\n <li>Darkvision out to 120 feet and low-light vision.</li>\n <li>Spell resistance equal to 11 + class levels.</li>\n <li>+2 racial bonus on all saving throws (figured into the statistics for the character presented here). This trait replaces the rock gnome\'s racial bonus on saving throws against illusions.</li>\n <li>Add +1 to the Difficulty Class for all saving throws against illusion spells cast by svirfneblin. This adjustment stacks with those from similar effects, such as the Spell Focus feat.</li>\n <li>+1 racial bonus on attack rolls against kobolds and goblinoids.</li>\n <li>+4 dodge bonus to Armor Class against all creatures (figured into the statistics for the character presented here). This trait replaces the rock gnome\'s dodge bonus against giants.</li>\n <li>Automatic Languages: Undercommon, Gnome, Common. Bonus Languages: Dwarven, Elven, Giant, Goblin, Orc, Terran. This trait replaces the rock gnome\'s automatic and bonus languages.</li>\n <li>Spell-Like Abilities: 1/day-<i>blindness/deafness</i> (typical save DC 13), <i>blur</i>,  <i>disguise self</i>. Caster level equals the svirfneblin\'s class levels. The save DC is Charisma-based and include a +4 racial modifier. This trait replaces the rock gnome\'s spell-like abilities.</li>\n <li>Nondetection (Su): A svirfneblin has a continuous nondetection ability as the spell (caster level equal to class levels).</li>\n <li>+2 racial bonus on Craft (alchemy) and Listen checks.</li>\n <li>+2 racial bonus on Hide checks, which improves to +4 underground.</li>\n <li>Favored Class: Rogue.</li>\n <li>Level adjustment +3.</li>\n</ul><p>The svirfneblin warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p><p>Challenge Rating: Svirfneblin with levels in NPC classes have a CR equal to their character level. Svirfneblin with levels in PC classes have a CR equal to their character level +1.</p>\n</div>\n</div><div topic=\"Forest Gnome\" level=\"5\"><p><h5>Forest Gnome</h5></p><p>They are the smallest of all the gnomes, averaging 2 to 2-1/2 feet in height, but look just like regular gnomes except with bark-colored or gray-green skin, and eyes that can be brown or green as well as blue. A very long-lived people, forest gnomes have an average life expectancy of 500 years.</p><div topic=\"Forest Gnome Traits\" level=\"8\"><p><b>Forest Gnome Traits (Ex):</b> These traits are in addition to the rock gnome traits, except where noted.</p><p>-<i>pass without trace</i> (Su): A forest gnome has the innate ability to use <i>pass without trace</i> (self only, as a free action) as the spell cast by a druid of the forest gnome\'s class levels.</p><ul>\n <li>+1 racial bonus on attack rolls against kobolds, goblinoids, orcs, and reptilian humanoids.</li>\n <li>Automatic Languages: Gnome, Elven, Sylvan, and a simple language that enables them to communicate on a very basic level with forest animals (this replaces the rock gnome\'s <i>speak with animals</i> ability). Bonus Languages: Common, Draconic, Dwarven, Giant, Goblin, Orc. This trait replaces the rock gnome\'s automatic and bonus languages.</li>\n <li>+4 racial bonus on Hide checks, which improves to +8 in a wooded area.</li>\n</ul><p/>\n</div>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersG');
INSERT INTO monster VALUES (393,'Goblin','Goblin, 1st-Level Warrior',NULL,'Small','Humanoid','Goblinoid','1d8+1 (5 hp)','+1','30 ft. (6 squares)','15 (+1 size, +1 Dex, +2 leather armor, +1 light shield), touch 12, flat-footed 14','+1','-3','Morningstar +2 melee (1d6) or javelin +3 ranged (1d4)','Morningstar +2 melee (1d6) or javelin +3 ranged (1d4)','5 ft.','5 ft.','-','Darkvision 60 ft.','Fort +3, Ref +1, Will -1','Str 11, Dex 13, Con 12, Int 10, Wis 9, Cha 6','Hide +5, Listen +2, Move Silently +5, Ride +4, Spot +2',NULL,'Alertness',NULL,'Temperate plains','Gang (4-9), band (10-100 plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level), warband (10-24 with worg mounts), or tribe (40-400 plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 10-24 worgs, and 2-4 dire wolves)','1/3','Standard','Usually neutral evil','By character class','+0','','1st-level warrior goblin; CR 1/3; Small humanoid (goblinoid); HD 1d8+1; hp 5; Init +1; Spd 30 ft. (6 squares); AC 15 (+1 size, +1 dex, +2 leather armor, +1 light shield), touch 12, flat-footed 14; Base Atk +1; Grp -3; Atk +2 melee (1d6, morningstar) or +3 ranged (1d4, javelin); Full Atk +2 melee (1d6, morningstar) or +3 ranged (1d4, javelin); Space/Reach 5 ft./5 ft.; SA -; SQ Darkvision 60 ft.; AL NE; SV Fort +3, Ref +1, Will -1; Str 11, Dex 13, Con 12, Int 10, Wis 9, Cha 6\n\nSkills and Feats: Hide +5, Listen +2, Move Silently +5, Ride +4, Spot +2; Alertness','\n      <div topic=\"Goblin\" level=\"2\"><p><h2>Goblin</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Goblin, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Humanoid (Goblinoid)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+1 size, +1 Dex, +2 leather armor, +1 light shield), touch 12, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Morningstar +2 melee (1d6) or javelin +3 ranged (1d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Morningstar +2 melee (1d6) or javelin +3 ranged (1d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +1, Will -1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">